57	static void create_background(lv_obj_t *parent)
58	{
59	    ui_bg = lv_obj_create(parent);
60	    lv_obj_set_size(ui_bg, SCREEN_W, SCREEN_H);
61	    lv_obj_align(ui_bg, LV_ALIGN_CENTER, 0, 0);
62	    /* 不设 radius/clip_corner：圆形裁剪在软件渲染下要逐像素判断圆内外，
