65	    lv_obj_set_style_bg_color(ui_bg, lv_color_hex(0x050A15), 0);  /* 回退色：图加载失败时显示 */
66	    lv_obj_set_style_bg_opa(ui_bg, LV_OPA_COVER, 0);
67	    lv_obj_set_style_border_width(ui_bg, 0, 0);
68	    lv_obj_set_style_pad_all(ui_bg, 0, 0);
69	    lv_obj_clear_flag(ui_bg, LV_OBJ_FLAG_SCROLLABLE);
70	    lv_obj_clear_flag(ui_bg, LV_OBJ_FLAG_CLICKABLE);
71	
72	    /* 背景图：铺满 ui_bg，置于最底层（卡片在其上）。
73	     * 去掉 ring：圆形 border 描边也要逐像素算，软件渲染下贵。 */
74	    lv_obj_t *bg_img = lv_image_create(ui_bg);
75	    lv_image_set_src(bg_img, "/emmc/background.png");
76	    lv_obj_set_size(bg_img, SCREEN_W, SCREEN_H);
77	    lv_obj_align(bg_img, LV_ALIGN_CENTER, 0, 0);
78	    lv_obj_set_style_image_opa(bg_img, LV_OPA_COVER, 0);
79	    lv_obj_clear_flag(bg_img, LV_OBJ_FLAG_CLICKABLE);
