94	/* ========== 单个应用卡片 ==========
95	 * 三张胶囊卡片竖排居中：从上到下倒计时/秒表/AI应用，无水平偏移。
96	 * 名称用中文字体（montserrat 不含中文会显示[]）。 */
97	static void create_app_card(int8_t idx)
98	{
99	    const int16_t card_w = 280, card_h = 72;
100	    const int16_t y_start = 108, gap = 18;
101	
102	    ui_cards[idx] = lv_obj_create(ui_bg);
103	    lv_obj_set_size(ui_cards[idx], card_w, card_h);
104	    lv_obj_align(ui_cards[idx], LV_ALIGN_TOP_MID, 0, y_start + idx*(card_h+gap));
105	    lv_obj_set_style_radius(ui_cards[idx], card_h/2, 0);  /* 胶囊圆角 */
106	    lv_obj_set_style_pad_all(ui_cards[idx], 0, 0);
107	    lv_obj_set_style_border_width(ui_cards[idx], 2, 0);
108	
109	    /* 图标在左 */
110	    ui_icons[idx] = lv_label_create(ui_cards[idx]);
111	    lv_label_set_text(ui_icons[idx], apps[idx].icon);
112	    lv_obj_set_style_text_font(ui_icons[idx], &lv_font_montserrat_32, 0);
113	    lv_obj_align(ui_icons[idx], LV_ALIGN_LEFT_MID, 28, 0);
114	
115	    /* 名称在图标右侧，中文字体 */
116	    ui_names[idx] = lv_label_create(ui_cards[idx]);
117	    lv_label_set_text(ui_names[idx], apps[idx].name);
118	    lv_obj_set_style_text_font(ui_names[idx], font_manager_get_font(FONT_LARGE), 0);  /* 中文 24 号 */
119	    lv_obj_align(ui_names[idx], LV_ALIGN_LEFT_MID, 80, 0);
120	
121	    lv_obj_add_event_cb(ui_cards[idx], card_event_cb, LV_EVENT_ALL, (void*)(intptr_t)idx);
122	}
