124	/* ========== 卡片样式：默认态 / 按下态 ==========
125	 * 默认低亮；按下(PRESSED)给高亮反馈，松开(RELEASED)还原——不保留持续高亮。 */
126	static void set_card_default(int8_t i)
127	{
128	    lv_obj_set_style_border_color(ui_cards[i], COLOR_PURPLE, 0);
129	    lv_obj_set_style_border_width(ui_cards[i], 2, 0);
130	    lv_obj_set_style_bg_color(ui_cards[i], COLOR_PURPLE, 0);
131	    lv_obj_set_style_bg_opa(ui_cards[i], LV_OPA_10, 0);
132	    lv_obj_set_style_text_color(ui_icons[i], COLOR_PURPLE, 0);
133	    lv_obj_set_style_text_color(ui_names[i], COLOR_GRAY, 0);
134	}
135	
136	static void set_card_pressed(int8_t i)
137	{
138	    lv_obj_set_style_border_color(ui_cards[i], COLOR_CYAN, 0);
139	    lv_obj_set_style_border_width(ui_cards[i], 3, 0);
140	    lv_obj_set_style_bg_color(ui_cards[i], COLOR_CYAN, 0);
141	    lv_obj_set_style_bg_opa(ui_cards[i], LV_OPA_30, 0);
142	    lv_obj_set_style_text_color(ui_icons[i], COLOR_CYAN, 0);
143	    lv_obj_set_style_text_color(ui_names[i], COLOR_WHITE, 0);
144	}
145	
146	static void card_event_cb(lv_event_t *e)
147	{
148	    lv_event_code_t code = lv_event_get_code(e);
149	    int8_t idx = (int8_t)(intptr_t)lv_event_get_user_data(e);
150	    if (code == LV_EVENT_PRESSED) {
151	        set_card_pressed(idx);        /* 按下即高亮 */
152	    } else if (code == LV_EVENT_RELEASED || code == LV_EVENT_PRESS_LOST) {
153	        set_card_default(idx);        /* 松开/失去按下即还原 */
154	    } else if (code == LV_EVENT_CLICKED) {
155	        if (apps[idx].launch_cb) apps[idx].launch_cb();
156	    }
157	}
