1	/****************************************************************************
2	 * apps/examples/xiaozhi_voice/mcp_server.c
3	 *
4	 * MCP (Model Context Protocol) tool server implementation.
5	 * Manages tool registration and dispatch for xiaozhi voice assistant.
6	 *
7	 * SPDX-License-Identifier: Apache-2.0
8	 ****************************************************************************/
9	
10	#include <nuttx/config.h>
11	#include <stdio.h>
12	#include <string.h>
13	#include <stdlib.h>
14	
15	#include <netutils/cJSON.h>
16	
17	#include "mcp_server.h"
18	
19	/****************************************************************************
20	 * Private Data
21	 ****************************************************************************/
22	
23	static struct mcp_server_s g_mcp;
24	
25	/****************************************************************************
26	 * Public Functions
27	 ****************************************************************************/
28	
29	void mcp_server_init(void)
30	{
31	  memset(&g_mcp, 0, sizeof(g_mcp));
32	  printf("[mcp] server initialized, max %d tools\n", MCP_MAX_TOOLS);
33	}
34	
35	int mcp_server_add_tool(const char *name,
36	                        const char *description,
37	                        const char *schema,
38	                        mcp_tool_cb_t callback)
39	{
40	  if (name == NULL || callback == NULL)
41	    {
42	      return -1;
43	    }
44	
45	  if (g_mcp.tool_count >= MCP_MAX_TOOLS)
46	    {
47	      printf("[mcp] ERROR: tool table full, cannot add '%s'\n", name);
48	      return -1;
49	    }
50	
51	  struct mcp_tool_s *tool = &g_mcp.tools[g_mcp.tool_count];
52	  strncpy(tool->name, name, MCP_TOOL_NAME_MAX - 1);
53	  tool->name[MCP_TOOL_NAME_MAX - 1] = '\0';
54	  strncpy(tool->description, description, MCP_TOOL_DESC_MAX - 1);
55	  tool->description[MCP_TOOL_DESC_MAX - 1] = '\0';
56	  if (schema != NULL)
57	    {
58	      strncpy(tool->schema, schema, MCP_TOOL_SCHEMA_MAX - 1);
59	      tool->schema[MCP_TOOL_SCHEMA_MAX - 1] = '\0';
60	    }
61	  else
62	    {
63	      tool->schema[0] = '\0';
64	    }
65	
66	  tool->callback = callback;
67	
68	  g_mcp.tool_count++;
69	  printf("[mcp] registered tool: %s — %s\n", name, description);
70	  return 0;
71	}
72	
73	static struct mcp_tool_s *find_tool(const char *name)
74	{
75	  int i;
76	  for (i = 0; i < g_mcp.tool_count; i++)
77	    {
78	      if (strcmp(g_mcp.tools[i].name, name) == 0)
79	        {
80	          return &g_mcp.tools[i];
81	        }
82	    }
83	
84	  return NULL;
85	}
86	
87	int mcp_server_handle_message(const cJSON *msg,
88	                              int (*send_json_cb)(cJSON *))
89	{
90	  if (msg == NULL || send_json_cb == NULL)
91	    {
92	      return -1;
93	    }
94	
95	  /* Server sends: {"type":"mcp","payload":{...},"session_id":"..."} */
96	
97	  cJSON *payload = cJSON_GetObjectItem(msg, "payload");
98	  if (!cJSON_IsObject(payload))
99	    {
100	      printf("[mcp] mcp message has no payload\n");
101	      return -1;
102	    }
103	
104	  /* Handle JSON-RPC method dispatch inside payload. */
105	
106	  cJSON *method = cJSON_GetObjectItem(payload, "method");
107	  cJSON *id_item = cJSON_GetObjectItem(payload, "id");
108	
109	  if (cJSON_IsString(method))
110	    {
111	      const char *method_name = method->valuestring;
112	      printf("[mcp] method: %s\n", method_name);
113	
114	      if (strcmp(method_name, "initialize") == 0)
115	        {
116	          /* Respond with server capabilities (JSON-RPC result). */
117	
118	          cJSON *resp = cJSON_CreateObject();
119	          cJSON_AddStringToObject(resp, "jsonrpc", "2.0");
120	          if (id_item != NULL)
121	            {
122	              cJSON_AddItemReferenceToObject(resp, "id", id_item);
123	            }
124	
125	          cJSON *result = cJSON_CreateObject();
126	          cJSON_AddStringToObject(result, "protocolVersion", "2024-11-05");
127	
128	          cJSON *caps = cJSON_CreateObject();
129	          cJSON *tools_caps = cJSON_CreateObject();
130	          cJSON_AddBoolToObject(tools_caps, "listChanged", false);
131	          cJSON_AddItemToObject(caps, "tools", tools_caps);
132	          cJSON_AddItemToObject(result, "capabilities", caps);
133	
134	          cJSON *server_info = cJSON_CreateObject();
135	          cJSON_AddStringToObject(server_info, "name", "xiaozhi-device");
136	          cJSON_AddStringToObject(server_info, "version", "1.0.0");
137	          cJSON_AddItemToObject(result, "serverInfo", server_info);
138	
139	          cJSON_AddItemToObject(resp, "result", result);
140	
141	          printf("[mcp] sending initialize response\n");
142	          int ret = send_json_cb(resp);
143	          cJSON_Delete(resp);
144	
145	          return ret;
146	        }
147	      else if (strcmp(method_name, "tools/list") == 0)
148	        {
149	          /* Respond with the list of registered tools. */
150	
151	          cJSON *resp = cJSON_CreateObject();
152	          cJSON_AddStringToObject(resp, "jsonrpc", "2.0");
153	          if (id_item != NULL)
154	            {
155	              cJSON_AddItemReferenceToObject(resp, "id", id_item);
156	            }
157	
158	          cJSON *result = cJSON_CreateObject();
159	          cJSON *tools_arr = cJSON_CreateArray();
160	
161	          int t;
162	          for (t = 0; t < g_mcp.tool_count; t++)
163	            {
164	              cJSON *tool_obj = cJSON_CreateObject();
165	              cJSON_AddStringToObject(tool_obj, "name",
166	                                      g_mcp.tools[t].name);
167	              cJSON_AddStringToObject(tool_obj, "description",
168	                                      g_mcp.tools[t].description);
169	
170	              /* Parse and add input schema. */
171	
172	              cJSON *schema = NULL;
173	              if (g_mcp.tools[t].schema[0] != '\0')
174	                {
175	                  schema = cJSON_Parse(g_mcp.tools[t].schema);
176	                }
177	
178	              if (schema == NULL)
179	                {
180	                  schema = cJSON_CreateObject();
181	                }
182	
183	              cJSON_AddItemToObject(tool_obj, "inputSchema", schema);
184	              cJSON_AddItemToArray(tools_arr, tool_obj);
185	            }
186	
187	          cJSON_AddItemToObject(result, "tools", tools_arr);
188	          cJSON_AddItemToObject(resp, "result", result);
189	
190	          printf("[mcp] tools/list response: %d tools\n",
191	                 g_mcp.tool_count);
192	          int ret = send_json_cb(resp);
193	          cJSON_Delete(resp);
194	          return ret;
195	        }
196	      else if (strcmp(method_name, "tools/call") == 0)
197	        {
198	          /* MCP tools/call: params contains name and arguments. */
199	
200	          cJSON *params = cJSON_GetObjectItem(payload, "params");
201	          cJSON *name_item = cJSON_GetObjectItem(params, "name");
202	          cJSON *args_item = cJSON_GetObjectItem(params, "arguments");
203	
204	          const char *tool_name = cJSON_IsString(name_item) ?
205	                                  name_item->valuestring : "";
206	
207	          printf("[mcp] tools/call: name=%s\n", tool_name);
208	
209	          struct mcp_tool_s *tool = find_tool(tool_name);
210	          cJSON *tool_result = NULL;
211	
212	          if (tool != NULL)
213	            {
214	              printf("[mcp] executing tool: %s\n", tool_name);
215	              tool_result = tool->callback(args_item);
216	            }
217	          else
218	            {
219	              printf("[mcp] unknown tool: %s\n", tool_name);
220	            }
221	
222	          /* Build MCP tools/call response with content array. */
223	
224	          cJSON *resp = cJSON_CreateObject();
225	          cJSON_AddStringToObject(resp, "jsonrpc", "2.0");
226	          if (id_item != NULL)
227	            {
228	              cJSON_AddItemReferenceToObject(resp, "id", id_item);
229	            }
230	
231	          cJSON *result = cJSON_CreateObject();
232	          cJSON *content = cJSON_CreateArray();
233	          cJSON *content_entry = cJSON_CreateObject();
234	          cJSON_AddStringToObject(content_entry, "type", "text");
235	
236	          if (tool_result != NULL)
237	            {
238	              /* If it's a string, use its value directly; otherwise print. */
239	
240	              const char *text = cJSON_IsString(tool_result) ?
241	                                 tool_result->valuestring : NULL;
242	              if (text != NULL)
243	                {
244	                  cJSON_AddStringToObject(content_entry, "text", text);
245	                }
246	              else
247	                {
248	                  char *result_str = cJSON_PrintUnformatted(tool_result);
249	                  cJSON_AddStringToObject(content_entry, "text",
250	                                          result_str ? result_str : "null");
251	                  free(result_str);
252	                }
253	            }
254	          else
255	            {
256	              cJSON_AddStringToObject(content_entry, "text", "null");
257	            }
258	
259	          cJSON_AddItemToArray(content, content_entry);
260	          cJSON_AddItemToObject(result, "content", content);
261	          cJSON_AddBoolToObject(result, "isError", (tool == NULL));
262	
263	          cJSON_AddItemToObject(resp, "result", result);
264	
265	          printf("[mcp] tools/call response for %s\n", tool_name);
266	          int ret = send_json_cb(resp);
267	          cJSON_Delete(resp);
268	
269	          if (tool_result != NULL)
270	            {
271	              cJSON_Delete(tool_result);
272	            }
273	
274	          return ret;
275	        }
276	      else if (strcmp(method_name, "notifications/tools/list_changed") == 0)
277	        {
278	          printf("[mcp] tools list changed notification, ignored\n");
279	          return 0;
280	        }
281	    }
282	
283	  printf("[mcp] unhandled message\n");
284	  return -1;
285	}
