101	/* MCP tool: send_json wrapper (app context via static pointer).
102	 * Wraps the JSON-RPC response in the xiaozhi transport format:
103	 * {"type":"mcp","payload":{...}}
104	 */
105	
106	static int mcp_send_json(cJSON *msg)
107	{
108	  if (s_mcp_app == NULL)
109	    {
110	      return -1;
111	    }
112	
113	  /* Wrap in transport format: {"type":"mcp","payload":<original>} */
114	
115	  cJSON *wrapper = cJSON_CreateObject();
116	  cJSON_AddStringToObject(wrapper, "type", "mcp");
117	  cJSON *payload = cJSON_Duplicate(msg, 1);
118	  cJSON_AddItemToObject(wrapper, "payload", payload);
119	
120	  int ret = send_json(s_mcp_app, wrapper);
121	  cJSON_Delete(wrapper);
122	  return ret;
123	}
