268	/****************************************************************************
269	 * Listening动画函数
270	 ****************************************************************************/
271	
272	/* 生成目标高度 */
273	static void wave_gen_targets(void)
274	{
275	    for (int i = 0; i < BAR_COUNT; i++) {
276	        float t = (float)i / BAR_COUNT;
277	        float env = expf(-5.0f * (t - 0.5f) * (t - 0.5f));
278	        float r = fabsf(sinf(t * 13.7f + s_tick * 0.9f)) * 0.4f
279	                + fabsf(cosf(t * 23.1f - s_tick * 0.6f)) * 0.35f
280	                + fabsf(sinf(t * 7.3f + s_tick * 1.4f)) * 0.25f;
281	        s_bar_tgt[i] = r * env;
282	    }
283	}
284	
285	/* 定时器回调 */
286	static void wave_tick_cb(lv_timer_t *t)
287	{
288	    (void)t;
289	
290	    pthread_mutex_lock(&s_ui_mutex);
291	
292	    s_tick += 0.15f;
293	
294	    /* 每次都生成新的目标高度，让动画持续变化 */
295	    wave_gen_targets();
296	
297	    /* 更新每个柱子的高度和位置 */
298	    for (int i = 0; i < BAR_COUNT; i++) {
299	        float speed = 0.1f + (float)i / BAR_COUNT * 0.1f;  /* 加快响应速度 */
300	        s_bar_h[i] += (s_bar_tgt[i] - s_bar_h[i]) * speed;
301	
302	        /* 计算高度（像素） */
303	        int h = (int)(s_bar_h[i] * BAR_MAX_HEIGHT);
304	        if (h < 4) h = 4;
305	
306	        /* 更新柱子对象的高度和位置（保持底部对齐） */
307	        if (s_bars[i] != NULL) {
308	            lv_obj_set_height(s_bars[i], h);
309	            /* 底部对齐：y坐标 = 容器高度 - 柱子高度 */
310	            lv_obj_set_y(s_bars[i], BAR_MAX_HEIGHT + 10 - h);
311	        }
312	    }
313	
314	    pthread_mutex_unlock(&s_ui_mutex);
315	}
316	
317	/* 启动Listening动画 */
318	void wave_anim_start(lv_obj_t *parent)
319	{
320	    /* 如果已经创建，先停止 */
321	    wave_anim_stop();
322	
323	    memset(s_bar_h, 0, sizeof(s_bar_h));
324	    memset(s_bar_tgt, 0, sizeof(s_bar_tgt));
325	    s_tick = 0;
326	
327	    /* 创建柱子容器 */
328	    s_bar_container = lv_obj_create(parent);
329	    lv_obj_set_size(s_bar_container, 200, BAR_MAX_HEIGHT + 10);  /* 容器高度 */
330	    lv_obj_align(s_bar_container, LV_ALIGN_TOP_MID, 0, 55);     /* 在status_label(60)上面一点 */
331	    lv_obj_set_style_bg_opa(s_bar_container, LV_OPA_TRANSP, 0);
332	    lv_obj_set_style_border_width(s_bar_container, 0, 0);
333	    lv_obj_set_style_pad_all(s_bar_container, 0, 0);
334	    lv_obj_set_style_pad_top(s_bar_container, 0, 0);
335	    lv_obj_set_style_pad_bottom(s_bar_container, 0, 0);
336	    lv_obj_set_style_pad_left(s_bar_container, 0, 0);
337	    lv_obj_set_style_pad_right(s_bar_container, 0, 0);
338	    lv_obj_clear_flag(s_bar_container, LV_OBJ_FLAG_SCROLLABLE);
339	    lv_obj_clear_flag(s_bar_container, LV_OBJ_FLAG_HIDDEN);
340	
341	    /* 计算起始位置 */
342	    int total_width = BAR_COUNT * BAR_WIDTH + (BAR_COUNT - 1) * BAR_GAP;
343	    int x_start = (200 - total_width) / 2;
344	
345	    /* 创建7个柱子，底部对齐在容器底部 */
346	    for (int i = 0; i < BAR_COUNT; i++) {
347	        s_bars[i] = lv_obj_create(s_bar_container);
348	        lv_obj_set_size(s_bars[i], BAR_WIDTH, 4);  /* 初始高度4像素 */
349	        /* 柱子底部对齐：y坐标 = 容器高度 - 初始高度 */
350	        lv_obj_set_pos(s_bars[i], x_start + i * (BAR_WIDTH + BAR_GAP), BAR_MAX_HEIGHT + 10 - 4);
351	        lv_obj_set_style_bg_color(s_bars[i], lv_color_hex(BAR_COLOR), 0);
352	        lv_obj_set_style_bg_opa(s_bars[i], LV_OPA_COVER, 0);
353	        lv_obj_set_style_radius(s_bars[i], BAR_WIDTH / 2, 0);  /* 圆角 */
354	        lv_obj_set_style_border_width(s_bars[i], 0, 0);
355	        lv_obj_clear_flag(s_bars[i], LV_OBJ_FLAG_HIDDEN);
356	    }
357	
358	    /* 创建"我正在听..." label */
359	    s_listen_label = lv_label_create(parent);
360	    lv_label_set_text(s_listen_label, "我正在听...");
361	    lv_obj_set_style_text_font(s_listen_label, font_manager_get_font(FONT_LARGE), 0);
362	    lv_obj_set_style_text_color(s_listen_label, lv_color_hex(0xFF6900), 0);
363	    lv_obj_align(s_listen_label, LV_ALIGN_TOP_MID, 0, 170);  /* 在动画下方 */
364	
365	    wave_gen_targets();
366	    s_timer = lv_timer_create(wave_tick_cb, ANIM_MS, NULL);
367	
368	    printf("[xiaozhi] wave_anim_start: created %d bars\n", BAR_COUNT);
369	}
370	
371	/* 停止Listening动画 */
372	void wave_anim_stop(void)
373	{
374	    if (s_timer) { lv_timer_del(s_timer); s_timer = NULL; }
375	
376	    for (int i = 0; i < BAR_COUNT; i++) {
377	        if (s_bars[i]) { lv_obj_del(s_bars[i]); s_bars[i] = NULL; }
378	    }
379	
380	    if (s_bar_container) { lv_obj_del(s_bar_container); s_bar_container = NULL; }
381	    if (s_listen_label) { lv_obj_del(s_listen_label); s_listen_label = NULL; }
382	}
