384	/****************************************************************************
385	 * Thinking动画函数
386	 ****************************************************************************/
387	
388	/* 定时器回调：更新圆点大小 */
389	static void think_tick_cb(lv_timer_t *t)
390	{
391	    (void)t;
392	
393	    pthread_mutex_lock(&s_ui_mutex);
394	
395	    s_think_tick++;
396	
397	    for (int i = 0; i < DOT_COUNT; i++) {
398	        float phase = (float)(s_think_tick - i * 2) / 4.0f;  /* 调整相位 */
399	        float tri = 1.0f - fabsf(fmodf(phase, 2.0f) - 1.0f);
400	        int size = (int)(DOT_SIZE * (0.4f + tri * 0.6f));
401	
402	        if (s_dots[i] != NULL) {
403	            lv_obj_set_size(s_dots[i], size, size);
404	            lv_obj_set_style_radius(s_dots[i], size / 2, 0);
405	        }
406	    }
407	
408	    pthread_mutex_unlock(&s_ui_mutex);
409	}
410	
411	/* 启动Thinking动画 */
412	void think_anim_start(lv_obj_t *parent)
413	{
414	    /* 如果已经创建，先停止 */
415	    think_anim_stop();
416	
417	    s_think_tick = 0;
418	
419	    /* 创建圆点容器 */
420	    s_dot_container = lv_obj_create(parent);
421	    lv_obj_set_size(s_dot_container, 150, 40);
422	    lv_obj_align(s_dot_container, LV_ALIGN_TOP_MID, 0, 70);  /* 在status_label(60)下面 */
423	    lv_obj_set_style_bg_opa(s_dot_container, LV_OPA_TRANSP, 0);
424	    lv_obj_set_style_border_width(s_dot_container, 0, 0);
425	    lv_obj_set_style_pad_all(s_dot_container, 0, 0);
426	    lv_obj_clear_flag(s_dot_container, LV_OBJ_FLAG_SCROLLABLE);
427	    lv_obj_clear_flag(s_dot_container, LV_OBJ_FLAG_HIDDEN);
428	
429	    /* 计算起始位置 */
430	    int total_w = DOT_COUNT * DOT_SIZE + (DOT_COUNT - 1) * DOT_GAP;
431	    int x_start = (150 - total_w) / 2;
432	    int y_pos = (40 - DOT_SIZE) / 2;
433	
434	    /* 创建3个圆点 */
435	    for (int i = 0; i < DOT_COUNT; i++) {
436	        s_dots[i] = lv_obj_create(s_dot_container);
437	        lv_obj_set_size(s_dots[i], DOT_SIZE, DOT_SIZE);
438	        lv_obj_set_pos(s_dots[i], x_start + i * (DOT_SIZE + DOT_GAP), y_pos);
439	        lv_obj_set_style_bg_color(s_dots[i], lv_color_hex(0xFF6900), 0);
440	        lv_obj_set_style_bg_opa(s_dots[i], LV_OPA_COVER, 0);
441	        lv_obj_set_style_radius(s_dots[i], DOT_SIZE / 2, 0);  /* 圆形 */
442	        lv_obj_set_style_border_width(s_dots[i], 0, 0);
443	        lv_obj_clear_flag(s_dots[i], LV_OBJ_FLAG_HIDDEN);
444	    }
445	
446	    /* 创建"思考中..." label */
447	    s_think_label = lv_label_create(parent);
448	    lv_label_set_text(s_think_label, "思考中...");
449	    lv_obj_set_style_text_font(s_think_label, font_manager_get_font(FONT_LARGE), 0);
450	    lv_obj_set_style_text_color(s_think_label, lv_color_hex(0xFF6900), 0);
451	    lv_obj_align(s_think_label, LV_ALIGN_TOP_MID, 0, 120);  /* 在动画下方 */
452	
453	    s_think_timer = lv_timer_create(think_tick_cb, DOT_ANIM_MS, NULL);
454	
455	    printf("[xiaozhi] think_anim_start: created %d dots\n", DOT_COUNT);
456	}
