582	/* Sanitize UTF-8 text: replace fullwidth CJK punctuation with ASCII
583	 * equivalents so the limited CJK font (basic ideographs only) can render
584	 * all visible characters without falling back to [][].
585	 */
586	static void sanitize_text(char *dst, size_t dstsize, const char *src)
587	{
588	  size_t di = 0;
589	  const unsigned char *s = (const unsigned char *)src;
590	
591	  while (*s && di < dstsize - 1)
592	    {
593	      /* 3-byte UTF-8: U+0800 .. U+FFFF */
594	      if (s[0] >= 0xe0 && s[1] >= 0x80 && s[1] < 0xc0 &&
595	          s[2] >= 0x80 && s[2] < 0xc0)
596	        {
597	          unsigned int cp = ((unsigned int)(s[0] & 0x0f) << 12) |
598	                            ((unsigned int)(s[1] & 0x3f) << 6) |
599	                            ((unsigned int)(s[2] & 0x3f));
600	          const char *r = NULL;
601	
602	          switch (cp)
603	            {
604	              case 0xff0c: r = ",";  break;  /* ， */
605	              case 0x3002: r = ".";  break;  /* 。 */
606	              case 0xff01: r = "!";  break;  /* ！ */
607	              case 0xff1f: r = "?";  break;  /* ？ */
608	              case 0xff1a: r = ":";  break;  /* ： */
609	              case 0xff1b: r = ";";  break;  /* ； */
610	              case 0x3001: r = ",";  break;  /* 、 */
611	              case 0x201c: r = "\""; break;  /* " */
612	              case 0x201d: r = "\""; break;  /* " */
613	              case 0x2018: r = "'";  break;  /* ' */
614	              case 0x2019: r = "'";  break;  /* ' */
615	              case 0xff08: r = "(";  break;  /* （ */
616	              case 0xff09: r = ")";  break;  /* ） */
617	              case 0x300a: r = "<<"; break;  /* 《 */
618	              case 0x300b: r = ">>"; break;  /* 》 */
619	              case 0x2026: r = "..."; break; /* … */
620	              case 0x2014: r = "--"; break;  /* — */
621	              default:
622	                {
623	                  /* Keep the original character if it's in CJK range */
624	                  if (cp >= 0x4e00 && cp <= 0x9fa5)
625	                    {
626	                      dst[di++] = s[0];
627	                      dst[di++] = s[1];
628	                      dst[di++] = s[2];
629	                    }
630	                  else
631	                    {
632	                      /* Unknown char: skip */
633	                    }
634	                  s += 3;
635	                  continue;
636	                }
637	            }
638	
639	          /* Write replacement string */
640	          while (*r && di < dstsize - 1)
641	            {
642	              dst[di++] = *r++;
643	            }
644	
645	          s += 3;
646	        }
647	      /* 2-byte UTF-8: U+0080 .. U+07FF (skip, not CJK) */
648	      else if (s[0] >= 0xc0 && s[0] < 0xe0 && s[1] >= 0x80)
649	        {
650	          s += 2;
651	        }
652	      /* ASCII */
653	      else if (s[0] < 0x80)
654	        {
655	          dst[di++] = *s++;
656	        }
657	      else
658	        {
659	          /* Invalid UTF-8 byte, skip */
660	          s++;
661	        }
662	    }
663	
664	  dst[di] = '\0';
665	}
