682	/* Uplink worker: capture Opus frames and send as binary frames for the
683	 * given number of seconds.
684	 */
685	static void *uplink_worker(void *arg)
686	{
687	  struct uplink_ctx_s *uc = arg;
688	  struct xiaozhi_app_s *app = uc->app;
689	  uint8_t frame[XZ_OPUS_MAX];
690	  int frames = 0;
691	  int target_frames = (uc->seconds * 1000) / 60;   /* 60ms per frame */
692	
693	  printf("[xiaozhi] uplink: capturing %d frames (%ds)\n",
694	         target_frames, uc->seconds);
695	
696	  
697	  printf("[xiaozhi] app->ws_connected %d\n", app->ws_connected);
698	
699	  while (frames < target_frames && app->ws_connected)
700	    {
701	      printf("[xiaozhi] in while show, frames=%d, target=%d, connected=%d\n",
702	             frames, target_frames, app->ws_connected);
703	      ssize_t n = xiaozhi_audio_read_opus(app->audio, frame, sizeof(frame));
704	      printf("[xiaozhi] read_opus returned: %zd\n", n);
705	      if (n < 0)
706	        {
707	          printf("[xiaozhi] uplink read err: %zd\n", n);
708	          break;
709	        }
710	
711	      if (n > 0)
712	        {
713	          /* Debug: hex dump first Opus frames for format verification. */
714	          if (frames < 3)
715	            {
716	              printf("[xiaozhi] opus frame[%d] len=%zd\n", frames, n);
717	              for (ssize_t i = 0; i < n && i < 32; i++)
718	                {
719	                  printf("%02x ", frame[i]);
720	                }
721	              printf("\n");
722	            }
723	
724	          int ret = xiaozhi_ws_send_binary(&app->ws, frame, n);
725	          if (ret != 0)
726	            {
727	              printf("[xiaozhi] uplink send err: %d\n", ret);
728	              break;
729	            }
730	
731	          frames++;
732	        }
733	    }
734	
735	  printf("[xiaozhi] uplink: sent %d/%d frames\n", frames, target_frames);
736	  return NULL;
737	}
