739	/* Receive worker: parse server messages and feed TTS audio to the player.
740	 * Runs until ws is closed or a stop condition.
741	 */
742	static void recv_loop(struct xiaozhi_app_s *app, int max_ms,
743	                      bool stop_on_hello)
744	{
745	  int waited = 0;
746	
747	  while (app->ws_connected && waited < max_ms && !app->mcp_done)
748	    {
749	      const uint8_t *payload;
750	      size_t plen;
751	      bool is_binary;
752	      int ret;
753	
754	      ret = xiaozhi_ws_recv(&app->ws, &payload, &plen, &is_binary);
755	      if (ret != 0)
756	        {
757	          app->ws_connected = false;
758	          break;
759	        }
760	
761	      if (is_binary)
762	        {
763	          printf("[xiaozhi] <<< binary frame: %zu bytes\n", plen);
764	          /* Server TTS Opus frame -> feed to player. */
765	          if (app->tts_playing)
766	            {
767	              xiaozhi_audio_write_opus(app->audio, payload, plen);
768	            }
769	
770	          waited += 60;
771	          continue;
772	        }
773	
774	      /* Text frame: parse JSON. */
775	      {
776	        char *json = malloc(plen + 1);
777	        if (json == NULL)
778	          {
779	            continue;
780	          }
781	
782	        memcpy(json, payload, plen);
783	        json[plen] = '\0';
784	
785	        cJSON *root = cJSON_Parse(json);
786	        if (root != NULL)
787	          {
788	            /* Print all received text messages for debugging. */
789	            printf("[xiaozhi] <<< recv: %s\n", json);
790	
791	            cJSON *type = cJSON_GetObjectItem(root, "type");
792	            const char *tstr = cJSON_IsString(type) ?
793	              type->valuestring : "";
794	
795	            if (strcmp(tstr, "stt") == 0)
796	              {
797	                cJSON *text = cJSON_GetObjectItem(root, "text");
798	                const char *s = text ? text->valuestring : "?";
799	                printf("[xiaozhi] <<< STT: \"%s\"\n", s);
800	                app->got_stt = true;
801	                sanitize_text(app->stt_text, sizeof(app->stt_text), s);
802	              }
803	            else if (strcmp(tstr, "llm") == 0)
804	              {
805	                cJSON *text = cJSON_GetObjectItem(root, "text");
806	                printf("[xiaozhi] <<< LLM: \"%s\"\n",
807	                       text ? text->valuestring : "?");
808	              }
809	            else if (strcmp(tstr, "tts") == 0)
810	              {
811	                cJSON *state = cJSON_GetObjectItem(root, "state");
812	                const char *sstr = cJSON_IsString(state) ?
813	                  state->valuestring : "";
814	
815	                if (strcmp(sstr, "start") == 0)
816	                  {
817	                    pthread_mutex_lock(&s_ui_mutex);
818	                    app->tts_playing = true;
819	                    app->state = XZ_STATE_PLAYING;
820	                    pthread_mutex_unlock(&s_ui_mutex);
821	                    xiaozhi_audio_start_playback(app->audio);
822	                    printf("[xiaozhi] <<< TTS start\n");
823	                  }
824	                else if (strcmp(sstr, "stop") == 0)
825	                  {
826	                    app->tts_playing = false;
827	                    printf("[xiaozhi] <<< TTS stop\n");
828	                    xiaozhi_audio_stop_playback(app->audio);
829	                    cJSON_Delete(root);
830	                    free(json);
831	                    break;   /* end of this turn */
832	                  }
833	                else if (strcmp(sstr, "sentence_start") == 0)
834	                  {
835	                    cJSON *text = cJSON_GetObjectItem(root, "text");
836	                    const char *s = text ? text->valuestring : "?";
837	                    printf("[xiaozhi] <<< TTS: \"%s\"\n", s);
838	                    app->tts_sentences++;
839	                    sanitize_text(app->tts_text, sizeof(app->tts_text), s);
840	                  }
841	              }
842	            else if (strcmp(tstr, "goodbye") == 0)
843	              {
844	                printf("[xiaozhi] <<< goodbye\n");
845	                app->ws_connected = false;
846	                cJSON_Delete(root);
847	                free(json);
848	                break;
849	              }
850	            else if (strcmp(tstr, "mcp") == 0)
851	              {
852	                printf("[xiaozhi] <<< MCP message\n");
853	                /* Check if this is tools/list — after responding, the MCP
854	                 * handshake is complete and we should proceed to listen.
855	                 */
856	                cJSON *payload = cJSON_GetObjectItem(root, "payload");
857	                cJSON *method = payload ?
858	                  cJSON_GetObjectItem(payload, "method") : NULL;
859	                bool is_tools_list = cJSON_IsString(method) &&
860	                  strcmp(method->valuestring, "tools/list") == 0;
861	
862	                mcp_server_handle_message(root, mcp_send_json);
863	
864	                if (is_tools_list)
865	                  {
866	                    printf("[xiaozhi] MCP handshake done\n");
867	                    app->mcp_done = true;
868	                  }
869	              }
870	            else if (strcmp(tstr, "hello") == 0)
871	              {
872	                cJSON *sid = cJSON_GetObjectItem(root, "session_id");
873	                if (cJSON_IsString(sid))
874	                  {
875	                    strncpy(app->session_id, sid->valuestring,
876	                            sizeof(app->session_id) - 1);
877	                    app->session_id[sizeof(app->session_id) - 1] = '\0';
878	                    printf("[xiaozhi] <<< hello: session_id=%s\n",
879	                           app->session_id);
880	                  }
881	
882	                /* In the connect phase we only need the hello response to
883	                 * obtain the session_id; bail out so we don't block here
884	                 * waiting for server audio that never comes before we've
885	                 * sent listen:start. The server also times out (~10s) if
886	                 * it doesn't see a listen request soon after hello.
887	                 */
888	                if (stop_on_hello)
889	                  {
890	                    cJSON_Delete(root);
891	                    free(json);
892	                    return;
893	                  }
894	              }
895	            else
896	              {
897	                /* Print full message for debugging unknown types (e.g. error). */
898	                char *out = cJSON_PrintUnformatted(root);
899	                printf("[xiaozhi] <<< %s\n", out ? out : tstr);
900	                if (out)
901	                  {
902	                    free(out);
903	                  }
904	              }
905	
906	            cJSON_Delete(root);
907	          }
908	        else
909	          {
910	            printf("[xiaozhi] <<< (parse err) %.*s\n",
911	                   (int)plen, (const char *)payload);
912	          }
913	
914	        free(json);
915	      }
916	
917	      waited += 60;
918	    }
919	}
