921	/* Dialog thread: runs the full OTA -> dialog flow off the main (UI) thread.
922	 */
923	static void *dialog_thread(void *arg)
924	{
925	  struct xiaozhi_app_s *app = arg;
926	  struct xiaozhi_ota_config_s ota;
927	  const char *mac = XIAOZHI_MAC_DEFAULT;
928	  char client_id[40];
929	  int ret;
930	
931	  snprintf(client_id, sizeof(client_id),
932	           "00000000-0000-0000-0000-%08x", 0xa1b2c3d7);
933	
934	  /* Init audio subsystem (creates Opus encoder). */
935	  app->audio = xiaozhi_audio_init();
936	  if (app->audio == NULL)
937	    {
938	      printf("[xiaozhi] audio init failed\n");
939	      app->state = XZ_STATE_ERROR;
940	      return NULL;
941	    }
942	
943	  /* Init MCP tool server and set app context for send callback. */
944	
945	  s_mcp_app = app;
946	  mcp_register_tools();
947	
948	  /* Step 1: OTA. */
949	  app->state = XZ_STATE_OTA;
950	  printf("[xiaozhi] step 1: OTA\n");
951	  ret = xiaozhi_ota_fetch(mac, &ota);
952	  if (ret != 0)
953	    {
954	      printf("[xiaozhi] OTA failed: %d\n", ret);
955	      app->state = XZ_STATE_ERROR;
956	      return NULL;
957	    }
958	
959	  /* Step 2: wss connect (TLS + ws upgrade). */
960	  app->state = XZ_STATE_CONNECT;
961	  printf("[xiaozhi] step 2: wss connect\n");
962	  ret = xiaozhi_ws_connect(&app->ws, ota.ws_url, ota.ws_token, mac,
963	                           client_id);
964	  if (ret != 0)
965	    {
966	      printf("[xiaozhi] ws connect failed: %d\n", ret);
967	      app->state = XZ_STATE_ERROR;
968	      return NULL;
969	    }
970	
971	  app->ws_connected = true;
972	
973	  /* Step 3: send the hello handshake, then wait for the server's hello
974	   * response which carries the session_id. The server times out (~10s)
975	   * if it never receives a hello, so we must send ours first.
976	   */
977	  printf("[xiaozhi] step 3: send hello + wait hello response\n");
978	  {
979	    cJSON *hello = cJSON_CreateObject();
980	    cJSON_AddStringToObject(hello, "type", "hello");
981	    cJSON_AddNumberToObject(hello, "version", 3);
982	    cJSON_AddStringToObject(hello, "transport", "websocket");
983	
984	    cJSON *ap = cJSON_CreateObject();
985	    cJSON_AddStringToObject(ap, "format", "opus");
986	    cJSON_AddNumberToObject(ap, "sample_rate", 16000);
987	    cJSON_AddNumberToObject(ap, "channels", 1);
988	    cJSON_AddNumberToObject(ap, "frame_duration", 60);
989	    cJSON_AddItemToObject(hello, "audio_params", ap);
990	
991	    /* Advertise MCP tool support to the server. */
992	
993	    mcp_server_add_hello_features(hello);
994	
995	    char *hello_str = cJSON_PrintUnformatted(hello);
996	    printf("[xiaozhi] >>> hello json: %s\n", hello_str ? hello_str : "null");
997	    if (hello_str)
998	      {
999	        free(hello_str);
1000	      }
1001	    ret = send_json(app, hello);
1002	    cJSON_Delete(hello);
1003	    if (ret != 0)
1004	      {
1005	        printf("[xiaozhi] hello send failed: %d\n", ret);
1006	        pthread_mutex_lock(&s_ui_mutex);
1007	        app->state = XZ_STATE_ERROR;
1008	        pthread_mutex_unlock(&s_ui_mutex);
1009	        goto out;
1010	      }
1011	  }
1012	
1013	  /* Receive the server hello response to get session_id. stop_on_hello
1014	   * returns immediately once we have it, so we don't block waiting for
1015	   * audio the server won't send before listen:start.
1016	   */
1017	  recv_loop(app, 5000, true);
1018	  if (app->session_id[0] == '\0')
1019	    {
1020	      printf("[xiaozhi] no session_id, abort\n");
1021	      pthread_mutex_lock(&s_ui_mutex);
1022	      app->state = XZ_STATE_ERROR;
1023	      pthread_mutex_unlock(&s_ui_mutex);
1024	      goto out;
1025	    }
1026	
1027	  /* Step 3b: Process MCP initialize from server.
1028	   * The server may send MCP initialize after hello but before we start
1029	   * listening. We need to handle it so the server knows our tools.
1030	   * The loop breaks early once tools/list is handled (mcp_done flag).
1031	   */
1032	
1033	  printf("[xiaozhi] step 3b: wait for MCP initialize\n");
1034	  app->mcp_done = false;
1035	  recv_loop(app, 3000, false);
1036	
1037	  /* Check if connection survived the MCP exchange.
1038	   * The TLS read may fail during recv_loop (error -0x5), killing
1039	   * the connection. If so, abort instead of continuing with a dead
1040	   * connection which would cause the dialog to loop forever.
1041	   */
1042	  if (!app->ws_connected)
1043	    {
1044	      printf("[xiaozhi] connection lost during MCP exchange, abort\n");
1045	      goto out;
1046	    }
1047	
1048	  /* Step 4: listen start + capture + listen stop. */
1049	  pthread_mutex_lock(&s_ui_mutex);
1050	  app->state = XZ_STATE_LISTENING;
1051	  pthread_mutex_unlock(&s_ui_mutex);
1052	  printf("[xiaozhi] step 4: listen start + capture, session_id=%s\n",
1053	         app->session_id);
1054	  {
1055	    cJSON *listen = cJSON_CreateObject();
1056	    cJSON_AddStringToObject(listen, "session_id", app->session_id);
1057	    cJSON_AddStringToObject(listen, "type", "listen");
1058	    cJSON_AddStringToObject(listen, "state", "start");
1059	    cJSON_AddStringToObject(listen, "mode", "manual");
1060	    char *json_str = cJSON_PrintUnformatted(listen);
1061	    printf("[xiaozhi] >>> listen start json: %s\n", json_str ? json_str : "null");
1062	    if (json_str)
1063	      {
1064	        free(json_str);
1065	      }
1066	    send_json(app, listen);
1067	    cJSON_Delete(listen);
1068	  }
1069	
1070	  ret = xiaozhi_audio_start_capture(app->audio);
1071	  if (ret != 0)
1072	    {
1073	      printf("[xiaozhi] capture start failed: %d\n", ret);
1074	      pthread_mutex_lock(&s_ui_mutex);
1075	      app->state = XZ_STATE_ERROR;
1076	      pthread_mutex_unlock(&s_ui_mutex);
1077	      goto out;
1078	    }
1079	
1080	  {
1081	    struct uplink_ctx_s uc;
1082	    uc.app = app;
1083	    uc.seconds = XZ_DIALOG_SECONDS;
1084	    uplink_worker(&uc);
1085	  }
1086	
1087	  xiaozhi_audio_stop_capture(app->audio);
1088	
1089	  /* listen stop. */
1090	  {
1091	    cJSON *stop = cJSON_CreateObject();
1092	    cJSON_AddStringToObject(stop, "session_id", app->session_id);
1093	    cJSON_AddStringToObject(stop, "type", "listen");
1094	    cJSON_AddStringToObject(stop, "state", "stop");
1095	    char *json_str = cJSON_PrintUnformatted(stop);
1096	    printf("[xiaozhi] >>> listen stop json: %s\n", json_str ? json_str : "null");
1097	    if (json_str)
1098	      {
1099	        free(json_str);
1100	      }
1101	    send_json(app, stop);
1102	    cJSON_Delete(stop);
1103	  }
1104	
1105	  /* Step 5: receive stt + tts + playback (up to 20s). */
1106	  app->state = XZ_STATE_THINKING;
1107	  printf("[xiaozhi] step 5: wait stt/tts (20s)\n");
1108	  app->mcp_done = false;  /* Reset so recv_loop doesn't exit early. */
1109	  recv_loop(app, 20000, false);
1110	
1111	out:
1112	  if (app->tts_playing)
1113	    {
1114	      xiaozhi_audio_stop_playback(app->audio);
1115	    }
1116	
1117	  xiaozhi_audio_deinit(app->audio);
1118	  xiaozhi_ws_close(&app->ws);
1119	
1120	  pthread_mutex_lock(&s_ui_mutex);
1121	  app->state = XZ_STATE_DONE;
1122	  pthread_mutex_unlock(&s_ui_mutex);
1123	  printf("[xiaozhi] === done: stt=%s tts=%d ===\n",
1124	         app->got_stt ? "yes" : "no", app->tts_sentences);
1125	
1126	  /* Reset state so user can start a new conversation. */
1127	  app->dialog_started = false;
1128	  app->ws_connected = false;
1129	  app->mcp_done = false;
1130	  app->got_stt = false;
1131	  app->tts_playing = false;
1132	  app->tts_sentences = 0;
1133	  memset(app->session_id, 0, sizeof(app->session_id));
1134	  memset(app->stt_text, 0, sizeof(app->stt_text));
1135	  memset(app->tts_text, 0, sizeof(app->tts_text));
1136	
1137	  /* Set flag to show start button - LVGL timer will handle the actual LVGL operation.
1138	   * Do NOT call lv_obj_clear_flag directly from this thread! */
1139	  app->show_start_btn = true;
1140	
1141	  return NULL;
1142	}
