1144	/* Start button click handler: kicks off the dialog thread on demand.
1145	 * The user taps this after WiFi is up, so OTA can reach the server.
1146	 */
1147	static void start_btn_event_cb(lv_event_t *e)
1148	{
1149	  struct xiaozhi_app_s *app = &g_app;
1150	  LV_UNUSED(e);
1151	
1152	  if (app->dialog_started)
1153	    {
1154	      return;   /* already running */
1155	    }
1156	
1157	  pthread_mutex_lock(&s_ui_mutex);
1158	  app->dialog_started = true;
1159	  app->state = XZ_STATE_OTA;
1160	  pthread_mutex_unlock(&s_ui_mutex);
1161	
1162	  /* Hide the start button once the dialog is launched. */
1163	  if (app->start_btn != NULL)
1164	    {
1165	      lv_obj_add_flag(app->start_btn, LV_OBJ_FLAG_HIDDEN);
1166	    }
1167	
1168	  pthread_attr_t attr;
1169	  pthread_attr_init(&attr);
1170	  pthread_attr_setstacksize(&attr, 65536);
1171	
1172	  int ret = pthread_create(NULL, &attr, dialog_thread, app);
1173	  pthread_attr_destroy(&attr);
1174	
1175	  if (ret != 0)
1176	    {
1177	      printf("[xiaozhi] dialog thread create failed: %d\n", ret);
1178	      pthread_mutex_lock(&s_ui_mutex);
1179	      app->state = XZ_STATE_ERROR;
1180	      app->dialog_started = false;
1181	      pthread_mutex_unlock(&s_ui_mutex);
1182	      if (app->start_btn != NULL)
1183	        {
1184	          lv_obj_clear_flag(app->start_btn, LV_OBJ_FLAG_HIDDEN);
1185	        }
1186	    }
1187	}
