1290	/* Refresh the LVGL screen from the shared app state.
1291	 * NOTE: This function performs LVGL operations and should only be called
1292	 * from LVGL timer callbacks (which run in the LVGL thread context).
1293	 * Do NOT call this from dialog_thread or any other thread directly.
1294	 */
1295	static void ui_refresh(struct xiaozhi_app_s *app)
1296	{
1297	  if (app->status_label != NULL)
1298	    {
1299	      lv_label_set_text(app->status_label, g_state_names[app->state]);
1300	    }
1301	
1302	  /* Only start/stop animations on state transitions, not every refresh. */
1303	  static int last_state = -1;
1304	  if (last_state != app->state)
1305	    {
1306	      /* 先停止所有动画 */
1307	      wave_anim_stop();
1308	      think_anim_stop();
1309	
1310	      if (app->state == XZ_STATE_LISTENING)
1311	        {
1312	          /* Listening状态：显示波形动画 */
1313	          if (xiaozhi_container != NULL)
1314	            {
1315	              wave_anim_start(xiaozhi_container);
1316	            }
1317	          /* You/Xiaozhi往下移动，避免被动画遮挡（动画底部约y=165） */
1318	          if (s_stt_caption != NULL)
1319	            {
1320	              lv_obj_align(s_stt_caption, LV_ALIGN_TOP_MID, 0, 190);
1321	            }
1322	          if (app->stt_label != NULL)
1323	            {
1324	              lv_obj_align(app->stt_label, LV_ALIGN_TOP_MID, 0, 220);
1325	            }
1326	          if (s_tts_caption != NULL)
1327	            {
1328	              lv_obj_align(s_tts_caption, LV_ALIGN_TOP_MID, 0, 280);
1329	            }
1330	          if (app->tts_label != NULL)
1331	            {
1332	              lv_obj_align(app->tts_label, LV_ALIGN_TOP_MID, 0, 310);
1333	            }
1334	        }
1335	      else if (app->state == XZ_STATE_THINKING)
1336	        {
1337	          /* Thinking状态：显示3个点动画 */
1338	          if (xiaozhi_container != NULL)
1339	            {
1340	              think_anim_start(xiaozhi_container);
1341	            }
1342	          /* You/Xiaozhi往下移动，避免被动画遮挡（动画底部约y=110） */
1343	          if (s_stt_caption != NULL)
1344	            {
1345	              lv_obj_align(s_stt_caption, LV_ALIGN_TOP_MID, 0, 150);
1346	            }
1347	          if (app->stt_label != NULL)
1348	            {
1349	              lv_obj_align(app->stt_label, LV_ALIGN_TOP_MID, 0, 180);
1350	            }
1351	          if (s_tts_caption != NULL)
1352	            {
1353	              lv_obj_align(s_tts_caption, LV_ALIGN_TOP_MID, 0, 240);
1354	            }
1355	          if (app->tts_label != NULL)
1356	            {
1357	              lv_obj_align(app->tts_label, LV_ALIGN_TOP_MID, 0, 270);
1358	            }
1359	        }
1360	      else if (app->state == XZ_STATE_PLAYING)
1361	        {
1362	          /* Playing状态：只隐藏label背景 */
1363	          if (s_stt_caption != NULL)
1364	            {
1365	              lv_obj_align(s_stt_caption, LV_ALIGN_TOP_MID, 0, 180);
1366	              lv_obj_set_style_bg_opa(s_stt_caption, LV_OPA_TRANSP, 0);
1367	            }
1368	          if (app->stt_label != NULL)
1369	            {
1370	              lv_obj_align(app->stt_label, LV_ALIGN_TOP_MID, 0, 210);
1371	              lv_obj_set_style_bg_opa(app->stt_label, LV_OPA_TRANSP, 0);
1372	            }
1373	          if (s_tts_caption != NULL)
1374	            {
1375	              lv_obj_align(s_tts_caption, LV_ALIGN_TOP_MID, 0, 270);
1376	              lv_obj_set_style_bg_opa(s_tts_caption, LV_OPA_TRANSP, 0);
1377	            }
1378	          if (app->tts_label != NULL)
1379	            {
1380	              lv_obj_align(app->tts_label, LV_ALIGN_TOP_MID, 0, 300);
1381	              lv_obj_set_style_bg_opa(app->tts_label, LV_OPA_TRANSP, 0);
1382	            }
1383	        }
1384	      else
1385	        {
1386	          /* 其他状态：恢复默认位置 */
1387	          if (s_stt_caption != NULL)
1388	            {
1389	              lv_obj_align(s_stt_caption, LV_ALIGN_TOP_MID, 0, 180);
1390	            }
1391	          if (app->stt_label != NULL)
1392	            {
1393	              lv_obj_align(app->stt_label, LV_ALIGN_TOP_MID, 0, 210);
1394	            }
1395	          if (s_tts_caption != NULL)
1396	            {
1397	              lv_obj_align(s_tts_caption, LV_ALIGN_TOP_MID, 0, 270);
1398	            }
1399	          if (app->tts_label != NULL)
1400	            {
1401	              lv_obj_align(app->tts_label, LV_ALIGN_TOP_MID, 0, 300);
1402	            }
1403	        }
1404	
1405	      last_state = app->state;
1406	    }
1407	
1408	  if (app->stt_label != NULL)
1409	    {
1410	      bool has_stt = app->stt_text[0] != '\0';
1411	      lv_label_set_text(app->stt_label, has_stt ? app->stt_text : "-");
1412	
1413	      /* Playing状态隐藏背景，其他状态根据内容显示/隐藏 */
1414	      lv_opa_t bg_opa;
1415	      if (app->state == XZ_STATE_PLAYING)
1416	        {
1417	          bg_opa = LV_OPA_TRANSP;
1418	        }
1419	      else
1420	        {
1421	          bg_opa = has_stt ? LV_OPA_COVER : LV_OPA_TRANSP;
1422	        }
1423	      lv_obj_set_style_bg_opa(app->stt_label, bg_opa, 0);
1424	      if (s_stt_caption != NULL)
1425	        {
1426	          lv_obj_set_style_bg_opa(s_stt_caption, bg_opa, 0);
1427	        }
1428	    }
1429	
1430	  if (app->tts_label != NULL)
1431	    {
1432	      bool has_tts = app->tts_text[0] != '\0';
1433	      lv_label_set_text(app->tts_label, has_tts ? app->tts_text : "-");
1434	
1435	      /* Playing状态隐藏背景，其他状态根据内容显示/隐藏 */
1436	      lv_opa_t bg_opa;
1437	      if (app->state == XZ_STATE_PLAYING)
1438	        {
1439	          bg_opa = LV_OPA_TRANSP;
1440	        }
1441	      else
1442	        {
1443	          bg_opa = has_tts ? LV_OPA_COVER : LV_OPA_TRANSP;
1444	        }
1445	      lv_obj_set_style_bg_opa(app->tts_label, bg_opa, 0);
1446	      if (s_tts_caption != NULL)
1447	        {
1448	          lv_obj_set_style_bg_opa(s_tts_caption, bg_opa, 0);
1449	        }
1450	    }
1451	
1452	  /* Handle show_start_btn flag from dialog_thread. */
1453	  if (app->show_start_btn && app->start_btn != NULL)
1454	    {
1455	      lv_obj_clear_flag(app->start_btn, LV_OBJ_FLAG_HIDDEN);
1456	      app->show_start_btn = false;
1457	    }
1458	}
