1460	/* Timer callback to refresh UI periodically.
1461	 * NOTE: This runs in the LVGL timer thread context.
1462	 * Do NOT hold s_ui_mutex here - ui_refresh performs LVGL operations
1463	 * that should not be blocked by dialog_thread's network I/O.
1464	 */
