286	/* 生成目标高度 */
287	static void wave_gen_targets(void)
288	{
289	    for (int i = 0; i < BAR_COUNT; i++) {
290	        float t = (float)i / BAR_COUNT;
291	        float env = expf(-5.0f * (t - 0.5f) * (t - 0.5f));
292	        float r = fabsf(sinf(t * 13.7f + s_tick * 0.9f)) * 0.4f
293	                + fabsf(cosf(t * 23.1f - s_tick * 0.6f)) * 0.35f
294	                + fabsf(sinf(t * 7.3f + s_tick * 1.4f)) * 0.25f;
295	        s_bar_tgt[i] = r * env;
296	    }
297	}
298	
299	/* 定时器回调 */
300	static void wave_tick_cb(lv_timer_t *t)
301	{
302	    (void)t;
303	
304	    pthread_mutex_lock(&s_ui_mutex);
305	
306	    s_tick += 0.15f;
307	
308	    /* 每次都生成新的目标高度，让动画持续变化 */
309	    wave_gen_targets();
310	
311	    /* 更新每个柱子的高度和位置 */
312	    for (int i = 0; i < BAR_COUNT; i++) {
313	        float speed = 0.1f + (float)i / BAR_COUNT * 0.1f;  /* 加快响应速度 */
314	        s_bar_h[i] += (s_bar_tgt[i] - s_bar_h[i]) * speed;
315	
316	        /* 计算高度（像素） */
317	        int h = (int)(s_bar_h[i] * BAR_MAX_HEIGHT);
318	        if (h < 4) h = 4;
319	
320	        /* 更新柱子对象的高度和位置（保持底部对齐） */
321	        if (s_bars[i] != NULL) {
322	            lv_obj_set_height(s_bars[i], h);
323	            /* 底部对齐：y坐标 = 容器高度 - 柱子高度 */
324	            lv_obj_set_y(s_bars[i], BAR_MAX_HEIGHT + 10 - h);
325	        }
326	    }
327	
328	    pthread_mutex_unlock(&s_ui_mutex);
329	}
