1	/****************************************************************************
2	 * apps/examples/xiaozhi_voice/xiaozhi_audio.c
3	 *
4	 * Audio capture (mic -> Opus 16kHz) and playback (Opus 24kHz -> speaker)
5	 * using direct Opus API for encoding and Vela media framework for decoding.
6	 * The SMF framework's Opus encoder adds non-standard headers that break
7	 * compatibility with the xiaozhi server, so we use the Opus API directly
8	 * for encoding. For playback, the SMF decoder works correctly.
9	 *
10	 * SPDX-License-Identifier: Apache-2.0
11	 ****************************************************************************/
12	
13	#include <nuttx/config.h>
14	
15	#include <stdio.h>
16	#include <string.h>
17	#include <errno.h>
18	#include <pthread.h>
19	
20	#include <opus.h>
21	
22	#include <media_recorder.h>
23	#include <media_player.h>
24	#include <media_defs.h>
25	
26	#include "xiaozhi_audio.h"
27	
28	/****************************************************************************
29	 * Pre-processor Definitions
30	 ****************************************************************************/
31	
32	/* Uplink: 16kHz mono Opus encoding parameters (direct API). */
33	#define XZ_OPUS_SAMPLE_RATE  16000
34	#define XZ_OPUS_CHANNELS     1
35	#define XZ_OPUS_BITRATE      32000
36	#define XZ_OPUS_FRAME_MS     60
37	#define XZ_OPUS_APPLICATION  OPUS_APPLICATION_VOIP
38	#define XZ_OPUS_FRAME_SIZE   (XZ_OPUS_SAMPLE_RATE * XZ_OPUS_FRAME_MS / 1000)  /* 960 samples */
39	
40	/* PCM capture options: raw 16-bit mono 16kHz from mic via SMF. */
41	#define XZ_PCM_RECORDER_OPTIONS \
42	  "fmt=[rate=#16000,ch=#1,bits=#16,width=#2],enc=[keys=pcm,imin=#1920]"
43	
44	/* Downlink: 24kHz mono Opus (xiaozhi server TTS sample rate, SMF native format). */
45	#define XZ_PLAYER_OPTIONS \
46	  "oMediaScript=[codec=opus,rate=#24000,ch=#1,bits=#16]"
47	
48	/* Max single Opus frame we expect / send. */
49	#define XZ_OPUS_FRAME_MAX 512
50	
51	/* PCM read buffer size: one 60ms frame at 16kHz mono 16-bit = 1920 bytes. */
52	#define XZ_PCM_BUF_SIZE (XZ_OPUS_FRAME_SIZE * XZ_OPUS_CHANNELS * sizeof(opus_int16))
53	
54	/****************************************************************************
55	 * Private Data
56	 ****************************************************************************/
57	
58	struct xiaozhi_audio_s
59	{
60	  /* Recording path (mic -> PCM -> Opus encode -> send). */
61	  void             *recorder;       /* SMF recorder handle (void*). */
62	  OpusEncoder      *opus_encoder;   /* Direct Opus encoder. */
63	  opus_int16        pcm_buf[XZ_OPUS_FRAME_SIZE * XZ_OPUS_CHANNELS];
64	  uint8_t           opus_buf[XZ_OPUS_FRAME_MAX];
65	  pthread_mutex_t   enc_mutex;
66	
67	  /* Playback path (recv Opus -> SMF decode -> speaker). */
68	  void             *player;         /* SMF player handle (void*). */
69	};
70	
71	static struct xiaozhi_audio_s g_audio;
72	
73	/****************************************************************************
74	 * Public Functions
75	 ****************************************************************************/
76	
77	struct xiaozhi_audio_s *xiaozhi_audio_init(void)
78	{
79	  struct xiaozhi_audio_s *a = &g_audio;
80	  int err;
81	
82	  memset(a, 0, sizeof(*a));
83	  pthread_mutex_init(&a->enc_mutex, NULL);
84	
85	  /* Create Opus encoder: 16kHz mono, VOIP application, 60ms frames. */
86	  a->opus_encoder = opus_encoder_create(XZ_OPUS_SAMPLE_RATE,
87	                                        XZ_OPUS_CHANNELS,
88	                                        XZ_OPUS_APPLICATION,
89	                                        &err);
90	  if (a->opus_encoder == NULL)
91	    {
92	      printf("[xiaozhi] opus_encoder_create failed: %s\n", opus_strerror(err));
93	      return NULL;
94	    }
95	
96	  /* Configure encoder for xiaozhi compatibility. */
97	  opus_encoder_ctl(a->opus_encoder, OPUS_SET_BITRATE(XZ_OPUS_BITRATE));
98	  opus_encoder_ctl(a->opus_encoder, OPUS_SET_COMPLEXITY(5));
99	  opus_encoder_ctl(a->opus_encoder, OPUS_SET_SIGNAL(OPUS_SIGNAL_VOICE));
100	  opus_encoder_ctl(a->opus_encoder, OPUS_SET_LSB_DEPTH(16));
101	  /* Force 60ms frame size. */
102	  opus_encoder_ctl(a->opus_encoder, OPUS_SET_PACKET_LOSS_PERC(0));
103	
104	  printf("[xiaozhi] opus encoder created: %dHz %dch %dbps %dms frame\n",
105	         XZ_OPUS_SAMPLE_RATE, XZ_OPUS_CHANNELS, XZ_OPUS_BITRATE,
106	         XZ_OPUS_FRAME_MS);
107	
108	  return a;
109	}
110	
111	int xiaozhi_audio_start_capture(struct xiaozhi_audio_s *a)
112	{
113	  int ret;
114	
115	  if (a == NULL)
116	    {
117	      return -EINVAL;
118	    }
119	
120	  /* Tear down any previous recorder. */
121	  if (a->recorder != NULL)
122	    {
123	      media_recorder_stop(a->recorder);
124	      media_recorder_close(a->recorder);
125	      a->recorder = NULL;
126	    }
127	
128	  a->recorder = media_recorder_open(MEDIA_SOURCE_MIC);
129	  if (a->recorder == NULL)
130	    {
131	      printf("[xiaozhi] media_recorder_open failed\n");
132	      return -EIO;
133	    }
134	
135	  /* Buffer mode: capture raw PCM. We encode to Opus ourselves. */
136	  ret = media_recorder_prepare(a->recorder, NULL, XZ_PCM_RECORDER_OPTIONS);
137	  if (ret < 0)
138	    {
139	      printf("[xiaozhi] recorder prepare failed: %d\n", ret);
140	      media_recorder_close(a->recorder);
141	      a->recorder = NULL;
142	      return ret;
143	    }
144	
145	  ret = media_recorder_start(a->recorder);
146	  if (ret < 0)
147	    {
148	      printf("[xiaozhi] recorder start failed: %d\n", ret);
149	      media_recorder_close(a->recorder);
150	      a->recorder = NULL;
151	      return ret;
152	    }
153	
154	  printf("[xiaozhi] capture started (16k PCM -> opus encode)\n");
155	  return 0;
156	}
157	
158	ssize_t xiaozhi_audio_read_opus(struct xiaozhi_audio_s *a,
159	                                uint8_t *buf, size_t maxlen)
160	{
161	  ssize_t total = 0;
162	  ssize_t n;
163	  int encoded_bytes;
164	  int frame_samples;
165	
166	  if (a == NULL || a->recorder == NULL || buf == NULL)
167	    {
168	      return -EINVAL;
169	    }
170	
171	  /* Read exactly one 60ms PCM frame from the SMF recorder.
172	   * At 16kHz mono 16-bit, one 60ms frame = 960 samples = 1920 bytes.
173	   * media_recorder_read_data may return partial reads, so loop until
174	   * we have the full frame.
175	   */
176	  while (total < XZ_PCM_BUF_SIZE)
177	    {
178	      n = media_recorder_read_data(a->recorder,
179	                                   (uint8_t *)a->pcm_buf + total,
180	                                   XZ_PCM_BUF_SIZE - total);
181	      if (n <= 0)
182	        {
183	          printf("[xiaozhi] pcm read returned: %zd (got %zd/%d)\n",
184	                 n, total, XZ_PCM_BUF_SIZE);
185	          return n > 0 ? -EIO : n;
186	        }
187	
188	      total += n;
189	    }
190	
191	  /* Encode PCM to Opus. opus_encode takes sample count, not byte count.
192	   * frame_samples = total_bytes / (channels * bytes_per_sample)
193	   *               = 1920 / (1 * 2) = 960 samples for 60ms at 16kHz.
194	   */
195	  frame_samples = total / (XZ_OPUS_CHANNELS * sizeof(opus_int16));
196	  encoded_bytes = opus_encode(a->opus_encoder,
197	                              a->pcm_buf,
198	                              frame_samples,
199	                              a->opus_buf,
200	                              XZ_OPUS_FRAME_MAX);
201	  if (encoded_bytes < 0)
202	    {
203	      printf("[xiaozhi] opus_encode error: %s (samples=%d)\n",
204	             opus_strerror(encoded_bytes), frame_samples);
205	      return -EIO;
206	    }
207	
208	  /* Copy encoded frame to caller's buffer. */
209	  if ((size_t)encoded_bytes > maxlen)
210	    {
211	      printf("[xiaozhi] opus frame too large: %d > %zu\n", encoded_bytes, maxlen);
212	      return -ENOMEM;
213	    }
214	
215	  memcpy(buf, a->opus_buf, encoded_bytes);
216	
217	  return (ssize_t)encoded_bytes;
218	}
219	
220	int xiaozhi_audio_stop_capture(struct xiaozhi_audio_s *a)
221	{
222	  if (a == NULL || a->recorder == NULL)
223	    {
224	      return -EINVAL;
225	    }
226	
227	  media_recorder_stop(a->recorder);
228	  media_recorder_close(a->recorder);
229	  a->recorder = NULL;
230	  printf("[xiaozhi] capture stopped\n");
231	  return 0;
232	}
233	
234	int xiaozhi_audio_start_playback(struct xiaozhi_audio_s *a)
235	{
236	  int ret;
237	
238	  if (a == NULL)
239	    {
240	      return -EINVAL;
241	    }
242	
243	  if (a->player != NULL)
244	    {
245	      media_player_stop(a->player);
246	      media_player_close(a->player, 0);
247	      a->player = NULL;
248	    }
249	
250	  a->player = media_player_open(MEDIA_STREAM_MUSIC);
251	  if (a->player == NULL)
252	    {
253	      printf("[xiaozhi] media_player_open failed\n");
254	      return -EIO;
255	    }
256	
257	  /* Buffer mode: url = NULL. The framework decodes Opus; we feed encoded
258	   * frames via media_player_write_data().
259	   */
260	  ret = media_player_prepare(a->player, NULL, XZ_PLAYER_OPTIONS);
261	  if (ret < 0)
262	    {
263	      printf("[xiaozhi] player prepare failed: %d\n", ret);
264	      media_player_close(a->player, 0);
265	      a->player = NULL;
266	      return ret;
267	    }
268	
269	  ret = media_player_start(a->player);
270	  if (ret < 0)
271	    {
272	      printf("[xiaozhi] player start failed: %d\n", ret);
273	      media_player_close(a->player, 0);
274	      a->player = NULL;
275	      return ret;
276	    }
277	
278	  printf("[xiaozhi] playback started (24k opus)\n");
279	  return 0;
280	}
281	
282	int xiaozhi_audio_write_opus(struct xiaozhi_audio_s *a,
283	                             const uint8_t *data, size_t len)
284	{
285	  ssize_t ret;
286	
287	  if (a == NULL || a->player == NULL || data == NULL)
288	    {
289	      return -EINVAL;
290	    }
291	
292	  ret = media_player_write_data(a->player, data, len);
293	  if (ret < 0)
294	    {
295	      printf("[xiaozhi] player write_data failed: %zd\n", ret);
296	      return ret;
297	    }
298	
299	  return 0;
300	}
301	
302	int xiaozhi_audio_stop_playback(struct xiaozhi_audio_s *a)
303	{
304	  if (a == NULL || a->player == NULL)
305	    {
306	      return -EINVAL;
307	    }
308	
309	  media_player_stop(a->player);
310	  media_player_close(a->player, 0);
311	  a->player = NULL;
312	  printf("[xiaozhi] playback stopped\n");
313	  return 0;
314	}
315	
316	void xiaozhi_audio_deinit(struct xiaozhi_audio_s *a)
317	{
318	  if (a == NULL)
319	    {
320	      return;
321	    }
322	
323	  if (a->recorder != NULL)
324	    {
325	      media_recorder_stop(a->recorder);
326	      media_recorder_close(a->recorder);
327	      a->recorder = NULL;
328	    }
329	
330	  if (a->player != NULL)
331	    {
332	      media_player_stop(a->player);
333	      media_player_close(a->player, 0);
334	      a->player = NULL;
335	    }
336	
337	  if (a->opus_encoder != NULL)
338	    {
339	      opus_encoder_destroy(a->opus_encoder);
340	      a->opus_encoder = NULL;
341	    }
342	
343	  pthread_mutex_destroy(&a->enc_mutex);
344	}
